import { test, expect } from '@playwright/test';

test("Navigate to the home page and verify the hero section displays correct...", async ({ page }) => {
  await test.step("STEP_ID=plan-step-1 | goto", async () => {
    await page.goto(new URL("/", "http://localhost:5173").toString());
  });
  await test.step("STEP_ID=plan-step-2 | waitForLoad", async () => {
    await page.waitForLoadState('networkidle', { timeout: 1500 }).catch(() => {});
  });
  await test.step("STEP_ID=plan-step-3 | expectVisible", async () => {
    await expect(page.getByRole('heading', { name: "Welcome to TechStore", exact: true })).toBeVisible();
  });
  await test.step("STEP_ID=plan-step-4 | expectVisible", async () => {
    await expect(page.getByRole('link', { name: "Products", exact: true })).toBeVisible();
  });
  await test.step("STEP_ID=plan-step-5 | expectVisible", async () => {
    await expect(page.getByRole('link', { name: "Login", exact: true })).toBeVisible();
  });
});

